def locate_loop(successors, start):
    if isinstance(successors, (str, bytes)):
        raise TypeError('successors must be a sequence')
    try:
        links = tuple(successors)
    except TypeError as exc:
        raise TypeError('successors must be iterable') from exc

    def validate(value, name):
        if value is None:
            return
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f'{name} must be an integer or None')
        if value < 0 or value >= len(links):
            raise ValueError(f'{name} is out of range')

    validate(start, 'start')
    for index, value in enumerate(links):
        validate(value, f'successors[{index}]')
    if start is None:
        return None

    slow = start
    fast = start
    while True:
        slow = links[slow]
        if slow is None:
            return None
        fast = links[fast]
        if fast is None:
            return None
        fast = links[fast]
        if fast is None:
            return None
        if slow == fast:
            break

    seeker = start
    while seeker != slow:
        seeker = links[seeker]
        slow = links[slow]
    return links[seeker]

